steps.solution:
TOOLS = {
    "homework": ["timetable", "library"],
    "office": ["timetable", "send"],
}
ACTS = ["send"]

def may_run(agent, tool, yes):
    if tool not in TOOLS.get(agent, []):
        return False
    if tool in ACTS and not yes:
        return False
    return True

